effect.shader:
vec3 rgb2hsv(vec3 c){
  vec4 K = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
  vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
  vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
  float d = q.x - min(q.w, q.y);
  float e = 1.0e-10;
  return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}
vec3 hsv2rgb(vec3 c){
  vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec3 hsv = rgb2hsv(clamp(c, 0.0, 1.0));
  float sat = hsv.y;
  float boost = amount * (1.0 - smoothstep(0.0, falloff, abs(sat - 0.35)));
  hsv.y = clamp(hsv.y + boost, 0.0, 1.0);
  vec3 g = hsv2rgb(hsv);
  float skin = smoothstep(0.05, 0.20, hsv.x) * (1.0 - smoothstep(0.10, 0.22, hsv.x));
  g = mix(g, c, skin * protectSkin);
  vec3 col = mix(c, g, mixAmt);
  gl_FragColor = vec4(col * a, a);
}
